#!/usr/bin/env python3\n\"\"\"\nJIA Installation Verification Script\n\nThis script verifies that all required dependencies are properly installed\nand checks system configuration for JIA application.\n\nUsage:\n    python verify_installation.py\n    python verify_installation.py --detailed\n    python verify_installation.py --fix\n\"\"\"\n\nimport sys\nimport os\nimport subprocess\nfrom pathlib import Path\n\n# Color codes for terminal output\nGREEN = '\\033[92m'\nRED = '\\033[91m'\nYELLOW = '\\033[93m'\nBLUE = '\\033[94m'\nEND = '\\033[0m'\n\ndef print_header(text):\n    \"\"\"Print colored header\"\"\"\n    print(f\"\\n{BLUE}{'='*60}{END}\")\n    print(f\"{BLUE}{text:^60}{END}\")\n    print(f\"{BLUE}{'='*60}{END}\\n\")\n\ndef print_success(text):\n    \"\"\"Print green success message\"\"\"\n    print(f\"{GREEN}✓ {text}{END}\")\n\ndef print_error(text):\n    \"\"\"Print red error message\"\"\"\n    print(f\"{RED}✗ {text}{END}\")\n\ndef print_warning(text):\n    \"\"\"Print yellow warning message\"\"\"\n    print(f\"{YELLOW}⚠ {text}{END}\")\n\ndef check_python_version():\n    \"\"\"Check Python version\"\"\"\n    print_header(\"Python Version Check\")\n    version = sys.version_info\n    version_str = f\"{version.major}.{version.minor}.{version.micro}\"\n    \n    if version.major >= 3 and version.minor >= 8:\n        print_success(f\"Python {version_str} (Required: 3.8+)\")\n        return True\n    else:\n        print_error(f\"Python {version_str} - Upgrade to 3.8+ required\")\n        return False\n\ndef check_module(module_name, display_name=None):\n    \"\"\"Check if a module is installed\"\"\"\n    display_name = display_name or module_name\n    try:\n        __import__(module_name)\n        print_success(f\"{display_name} installed\")\n        return True\n    except ImportError:\n        print_error(f\"{display_name} NOT installed\")\n        return False\n\ndef check_core_dependencies():\n    \"\"\"Check core required dependencies\"\"\"\n    print_header(\"Core Dependencies Check\")\n    \n    modules = [\n        ('kivy', 'Kivy GUI Framework'),\n        ('kivymd', 'KivyMD Material Design'),\n        ('speech_recognition', 'Speech Recognition'),\n        ('pyttsx3', 'Text-to-Speech'),\n        ('mysql.connector', 'MySQL Connector'),\n        ('google.generativeai', 'Google Gemini API'),\n    ]\n    \n    results = []\n    for module, name in modules:\n        results.append(check_module(module, name))\n    \n    return all(results)\n\ndef check_optional_dependencies():\n    \"\"\"Check optional dependencies\"\"\"\n    print_header(\"Optional Dependencies Check\")\n    \n    optional_modules = [\n        ('requests', 'HTTP Requests'),\n        ('bs4', 'BeautifulSoup'),\n        ('pyautogui', 'Desktop Automation'),\n        ('plyer', 'System Notifications'),\n        ('playsound', 'Audio Playback'),\n        ('vosk', 'Offline Speech Recognition'),\n        ('googletrans', 'Google Translate'),\n        ('gtts', 'Google Text-to-Speech'),\n        ('pywhatkit', 'Web Automation'),\n        ('wikipedia', 'Wikipedia API'),\n        ('wolframalpha', 'Wolfram Alpha'),\n    ]\n    \n    missing = []\n    for module, name in optional_modules:\n        if not check_module(module, name):\n            missing.append(name)\n    \n    if missing:\n        print_warning(f\"Missing optional modules: {', '.join(missing)}\")\n        print(f\"Install with: pip install {' '.join([m[0] for m in optional_modules if m[1] in missing])}\")\n    else:\n        print_success(\"All optional modules installed\")\n    \n    return len(missing) == 0\n\ndef check_database():\n    \"\"\"Check MySQL database connectivity\"\"\"\n    print_header(\"Database Check\")\n    \n    try:\n        import mysql.connector\n        \n        # Try to connect to MySQL\n        try:\n            connection = mysql.connector.connect(\n                host='localhost',\n                user='root',\n                password='',  # Try empty password first\n                database='AIuser'\n            )\n            connection.close()\n            print_success(\"MySQL database 'AIuser' accessible\")\n            return True\n        except mysql.connector.Error as e:\n            if e.errno == 2003:\n                print_error(\"MySQL not running - Please start MySQL service\")\n            elif e.errno == 1045:\n                print_warning(\"MySQL running but authentication failed\")\n                print(\"  Configure credentials in CODE/CODE/AIAssistant/JIA.py\")\n            elif e.errno == 1049:\n                print_warning(\"Database 'AIuser' not found\")\n                print(\"  Create with: mysql -u root -p < aiuser.sql\")\n            else:\n                print_warning(f\"Database connection issue: {e.msg}\")\n            return False\n    except ImportError:\n        print_error(\"MySQL connector not installed\")\n        return False\n\ndef check_audio_devices():\n    \"\"\"Check audio input/output devices\"\"\"\n    print_header(\"Audio Devices Check\")\n    \n    try:\n        import speech_recognition as sr\n        \n        # Check microphones\n        mics = sr.Microphone.list_microphone_indexes()\n        if mics:\n            print_success(f\"Found {len(mics)} microphone(s)\")\n            for i in mics:\n                print(f\"  Device {i}: {sr.Microphone(device_index=i).get_pyaudio().get_device_info_by_index(i)['name']}\")\n        else:\n            print_error(\"No microphones detected\")\n            return False\n        \n        return True\n    except Exception as e:\n        print_warning(f\"Audio device check failed: {str(e)}\")\n        return False\n\ndef check_config_files():\n    \"\"\"Check for required configuration files\"\"\"\n    print_header(\"Configuration Files Check\")\n    \n    base_path = Path('CODE/CODE/AIAssistant')\n    required_files = [\n        base_path / 'JIA.py',\n        base_path / 'JIA.kv',\n        base_path / 'gemini.py',\n        base_path / 'stt.py',\n        base_path / 'tts.py',\n    ]\n    \n    all_exist = True\n    for file in required_files:\n        if file.exists():\n            print_success(f\"{file.name} found\")\n        else:\n            print_error(f\"{file.name} NOT found\")\n            all_exist = False\n    \n    # Check for .env file\n    if Path('.env').exists():\n        print_success(\".env configuration file found\")\n    else:\n        print_warning(\".env file not found - create from .env.example\")\n    \n    return all_exist\n\ndef check_api_key():\n    \"\"\"Check if Gemini API key is configured\"\"\"\n    print_header(\"API Configuration Check\")\n    \n    try:\n        # Try to read from gemini.py\n        with open('CODE/CODE/AIAssistant/gemini.py', 'r') as f:\n            content = f.read()\n            if 'googleapi=' in content:\n                if 'AIzaSy' in content:\n                    print_success(\"Gemini API key appears to be configured\")\n                    return True\n                else:\n                    print_warning(\"Gemini API key not configured or invalid\")\n                    print(\"  Set API key in CODE/CODE/AIAssistant/gemini.py\")\n                    print(\"  Get free API key from https://ai.google.dev/\")\n                    return False\n    except FileNotFoundError:\n        print_error(\"gemini.py not found\")\n        return False\n\ndef generate_report():\n    \"\"\"Generate installation report\"\"\"\n    print_header(\"JIA Installation Verification\")\n    \n    checks = [\n        (\"Python Version\", check_python_version()),\n        (\"Core Dependencies\", check_core_dependencies()),\n        (\"Optional Dependencies\", check_optional_dependencies()),\n        (\"Configuration Files\", check_config_files()),\n        (\"API Configuration\", check_api_key()),\n        (\"Database Connection\", check_database()),\n        (\"Audio Devices\", check_audio_devices()),\n    ]\n    \n    print_header(\"Verification Summary\")\n    \n    passed = sum(1 for _, result in checks if result)\n    total = len(checks)\n    \n    for check_name, result in checks:\n        status = f\"{GREEN}PASS{END}\" if result else f\"{RED}FAIL{END}\"\n        print(f\"{check_name}: {status}\")\n    \n    print(f\"\\nTotal: {passed}/{total} checks passed\")\n    \n    if passed == total:\n        print(f\"\\n{GREEN}✓ Installation complete! Ready to run: python CODE/CODE/AIAssistant/JIA.py{END}\")\n        return 0\n    else:\n        print(f\"\\n{RED}✗ Some checks failed. See above for details.{END}\")\n        return 1\n\ndef install_missing_dependencies():\n    \"\"\"Attempt to install missing dependencies\"\"\"\n    print_header(\"Installing Missing Dependencies\")\n    \n    try:\n        subprocess.check_call([sys.executable, '-m', 'pip', 'install', '-r', 'requirements.txt'])\n        print_success(\"Dependencies installed successfully\")\n        return True\n    except subprocess.CalledProcessError:\n        print_error(\"Failed to install dependencies\")\n        return False\n\ndef main():\n    \"\"\"Main function\"\"\"\n    if '--help' in sys.argv or '-h' in sys.argv:\n        print(__doc__)\n        return 0\n    \n    if '--fix' in sys.argv:\n        install_missing_dependencies()\n    \n    return generate_report()\n\nif __name__ == '__main__':\n    sys.exit(main())\n"